use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn count_nodes(root:Option<Rc<RefCell<TreeNode>>>)->i32{fn h(mut n:Option<Rc<RefCell<TreeNode>>>,left:bool)->i32{let mut x=0;while let Some(v)=n{x+=1;n=if left{v.borrow().left.clone()}else{v.borrow().right.clone()};}x}if let Some(r)=root.clone(){let a=h(Some(r.clone()),true);let b=h(Some(r.clone()),false);if a==b{(1<<a)-1}else{1+Self::count_nodes(r.borrow().left.clone())+Self::count_nodes(r.borrow().right.clone())}}else{0}}}
